CREATE TABLE IF NOT EXISTS vendor_profiles(id UUID PRIMARY KEY REFERENCES vendors(id) ON DELETE CASCADE,owner_id UUID NOT NULL REFERENCES app_users(id),description VARCHAR(2000),verification_status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(verification_status IN ('PENDING','APPROVED','REJECTED')));
CREATE TABLE IF NOT EXISTS vendor_services(id UUID PRIMARY KEY,vendor_id UUID NOT NULL REFERENCES vendors(id) ON DELETE CASCADE,title VARCHAR(200) NOT NULL,base_price_paise BIGINT NOT NULL CHECK(base_price_paise>=0),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS vendor_quotes(id UUID PRIMARY KEY,enquiry_id UUID NOT NULL REFERENCES enquiries(id),vendor_id UUID NOT NULL REFERENCES vendors(id),amount_paise BIGINT NOT NULL CHECK(amount_paise>=0),description VARCHAR(2000),status VARCHAR(20) NOT NULL DEFAULT 'OFFERED' CHECK(status IN ('OFFERED','ACCEPTED','REJECTED','EXPIRED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vendor_bookings(id UUID PRIMARY KEY,quote_id UUID NOT NULL UNIQUE REFERENCES vendor_quotes(id),wedding_id UUID NOT NULL REFERENCES weddings(id),vendor_id UUID NOT NULL REFERENCES vendors(id),status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED' CHECK(status IN ('CONFIRMED','CANCELLED','COMPLETED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catering_menus(id UUID PRIMARY KEY,wedding_id UUID NOT NULL REFERENCES weddings(id) ON DELETE CASCADE,ceremony_id UUID REFERENCES ceremonies(id),meal VARCHAR(30) NOT NULL,guest_count INT NOT NULL CHECK(guest_count>0),UNIQUE(wedding_id,ceremony_id,meal));
CREATE TABLE IF NOT EXISTS catering_items(id UUID PRIMARY KEY,menu_id UUID NOT NULL REFERENCES catering_menus(id) ON DELETE CASCADE,name VARCHAR(150) NOT NULL,diet VARCHAR(20) NOT NULL CHECK(diet IN ('VEG','NON_VEG','JAIN')),quantity INT NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS payment_records(id UUID PRIMARY KEY,booking_id UUID NOT NULL REFERENCES vendor_bookings(id),amount_paise BIGINT NOT NULL CHECK(amount_paise>0),external_reference VARCHAR(200) UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','VERIFIED','FAILED','REFUNDED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_vendor_profiles_owner ON vendor_profiles(owner_id);
CREATE INDEX IF NOT EXISTS idx_quotes_enquiry ON vendor_quotes(enquiry_id);
CREATE INDEX IF NOT EXISTS idx_bookings_wedding ON vendor_bookings(wedding_id);
